={{
  ($node["AI Agent"].json.output || '') +
  (
    $('Set Docs Context').isExecuted
      ? (() => {
          const ctx = $items("Set Docs Context")[0]?.json || {};
          const sources = Array.isArray(ctx.sources)
            ? ctx.sources
            : JSON.parse(ctx.sources || '[]');

          const ragUsed = ctx.ragUsed === true || ctx.ragUsed === 'true';
          const usedFallback = ctx.usedFallback === true || ctx.usedFallback === 'true';

          return ragUsed && sources.length > 0 && !usedFallback
            ? "\n\n📚 Nguồn tham khảo:\n- " + [...new Set(sources)].join("\n- ")
            : "";
        })()
      : ""
  )
}}

