const text = $json.message.text || ''

const getField = (label) => {
  const regex = new RegExp(`${label}:\\s*(.+)`, 'i')
  const match = text.match(regex)
  return match ? match[1].trim() : ''
}

const email = getField('Email')
const issue = getField('Vấn đề')
const description = getField('Mô tả')
const priority = getField('Mức độ') || 'Bình thường'

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)

const missingFields = []

if (!email) missingFields.push('Email')
else if (!emailValid) missingFields.push('Email không hợp lệ')

if (!issue) missingFields.push('Vấn đề')
if (!description) missingFields.push('Mô tả')

return [
  {
    json: {
      email,
      issue,
      description,
      priority,
      emailValid,
      isValid: missingFields.length === 0,
      missingFields,
      telegramUserId: $json.message.from.id,
      telegramUsername: $json.message.from.username || $json.message.from.first_name || '',
      chatId: $json.message.chat.id,
      originalMessage: text
    }
  }
]

