const input = $input.first().json

let raw = '{}'

// Nếu Intent Router là HTTP Request gọi Groq
if (input.choices && input.choices[0] && input.choices[0].message) {
  raw = input.choices[0].message.content
}

// Nếu Intent Router là AI/node khác
else if (input.output) {
  raw = input.output
} else if (input.text) {
  raw = input.text
} else if (input.response) {
  raw = input.response
}

// Trường hợp Groq trả về mảng [{ choices: ... }]
else if (Array.isArray(input) && input[0]?.choices?.[0]?.message?.content) {
  raw = input[0].choices[0].message.content
}

// Dọn markdown nếu model lỡ trả ```json ... ```
raw = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim()

let parsed

try {
  parsed = JSON.parse(raw)
} catch (error) {
  parsed = {
    needDocs: true,
    intent: 'unknown',
    reason: 'Failed to parse router output, fallback to docs',
    raw
  }
}

const telegram = $('Telegram Trigger').first().json

return [
  {
    json: {
      userMessage: telegram.message?.text || '',
      needDocs: parsed.needDocs === true,
      intent: parsed.intent || 'unknown',
      routerReason: parsed.reason || '',
      routerRaw: raw
    }
  }
]

