function safeJsonParse(value) {
  if (typeof value !== "string") return value;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function isObject(value) {
  return value && typeof value === "object" && !Array.isArray(value);
}

function normalizeBoolean(value) {
  return value === true || value === "true";
}

// Input gốc từ n8n
const input = $json;

// Parse body nếu có
const body = input.body ? safeJsonParse(input.body) : null;

// Parse docsContext nếu nó đang là JSON string
const parsedDocsContext = input.docsContext
  ? safeJsonParse(input.docsContext)
  : null;

// Parse context nếu nó đang là JSON string
const parsedContext = input.context
  ? safeJsonParse(input.context)
  : null;

// Ưu tiên tìm context theo thứ tự rõ ràng
let realContext = "";

if (isObject(body) && typeof body.context === "string") {
  realContext = body.context;
} else if (isObject(parsedDocsContext) && typeof parsedDocsContext.context === "string") {
  realContext = parsedDocsContext.context;
} else if (isObject(parsedContext) && typeof parsedContext.context === "string") {
  realContext = parsedContext.context;
} else if (typeof input.context === "string" && !input.context.trim().startsWith("{")) {
  realContext = input.context;
} else if (typeof input.docsContext === "string" && !input.docsContext.trim().startsWith("{")) {
  realContext = input.docsContext;
}

// Lấy question/userMessage
let userMessage =
  input.userMessage ||
  input.question ||
  body?.question ||
  parsedDocsContext?.question ||
  parsedContext?.question ||
  "";

// Lấy sources
let sources =
  body?.sources ||
  parsedDocsContext?.sources ||
  parsedContext?.sources ||
  input.sources ||
  [];

sources = safeJsonParse(sources);
if (!Array.isArray(sources)) sources = [];

// Lấy noMatch
const noMatch =
  input.noMatch ??
  body?.noMatch ??
  parsedDocsContext?.noMatch ??
  parsedContext?.noMatch ??
  false;

return [
  {
    json: {
      userMessage,
      docsContext: realContext,
      noMatch: normalizeBoolean(noMatch),
      sources,
      ragUsed: normalizeBoolean(input.ragUsed),
      usedFallback: normalizeBoolean(input.usedFallback),
      intent: input.intent || "",
      routerReason: input.routerReason || "",
    },
  },
];

const input = $input.first().json;

let raw = input.output || input.text || input.response || '{}';

if (typeof raw === 'string') {
  raw = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

let extracted;
try {
  extracted = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [
    {
      json: {
        shouldUpdate: false,
        memory: null,
        error: 'Invalid JSON from Memory Extractor',
        raw,
      },
    },
  ];
}

let redisData = {};
let currentRaw = '{}';

try {
  redisData = $('Redis Get Long Memory').first().json;

  currentRaw =
    redisData.value ??
    redisData.data ??
    redisData.result ??
    redisData.longMemory ??
    redisData.memory ??
    null;

  // Nếu Redis node chỉ trả về 1 field, lấy field đó
  if (currentRaw === null) {
    const values = Object.values(redisData);
    if (values.length === 1) {
      currentRaw = values[0];
    }
  }

  if (currentRaw === null || currentRaw === undefined || currentRaw === '') {
    currentRaw = '{}';
  }
} catch (e) {
  currentRaw = '{}';
}

let currentMemory = {};
try {
  currentMemory =
    typeof currentRaw === 'string'
      ? JSON.parse(currentRaw)
      : currentRaw || {};
} catch (e) {
  currentMemory = {};
}

const newMemory = extracted.memory || {};

const mergedMemory = {
  name: newMemory.name ?? currentMemory.name ?? null,
  email: newMemory.email ?? currentMemory.email ?? null,
  language: newMemory.language ?? currentMemory.language ?? null,

  preferences:
    Array.isArray(newMemory.preferences) && newMemory.preferences.length > 0
      ? [...new Set([...(currentMemory.preferences || []), ...newMemory.preferences])]
      : currentMemory.preferences || [],

  known_facts:
    Array.isArray(newMemory.known_facts) && newMemory.known_facts.length > 0
      ? [...new Set([...(currentMemory.known_facts || []), ...newMemory.known_facts])]
      : currentMemory.known_facts || [],

  open_issue: newMemory.open_issue ?? currentMemory.open_issue ?? null,
};

return [
  {
    json: {
      shouldUpdate: extracted.shouldUpdate === true,
      memory: mergedMemory,

      debugRedisData: redisData,
      debugCurrentRaw: currentRaw,
      debugCurrentMemory: currentMemory,
      debugNewMemory: newMemory,
    },
  },
];
